#:package Microsoft.IdentityModel.JsonWebTokens@8.*
using System.Security.Claims;
using System.Text;
using Microsoft.IdentityModel.JsonWebTokens;
using Microsoft.IdentityModel.Tokens;

var handler = new JsonWebTokenHandler();
var key = new SymmetricSecurityKey(Encoding.UTF8.GetBytes("0123456789-0123456789-0123456789-ab"));
var creds = new SigningCredentials(key, SecurityAlgorithms.HmacSha256);

var now = DateTime.UtcNow;
var token = handler.CreateToken(new SecurityTokenDescriptor
{
    Subject = new ClaimsIdentity([new Claim("sub", "1")]),
    IssuedAt = now.AddMinutes(-17),
    NotBefore = now.AddMinutes(-17),
    Expires = now.AddMinutes(-2),          // đã hết hạn 2 phút
    SigningCredentials = creds
});

var p1 = new TokenValidationParameters {
    IssuerSigningKey = key,
    ValidateIssuer = false, ValidateAudience = false };
var p2 = p1.Clone();
p2.ClockSkew = TimeSpan.Zero;

Console.WriteLine((await handler.ValidateTokenAsync(token, p1)).IsValid);
Console.WriteLine((await handler.ValidateTokenAsync(token, p2)).IsValid);

