using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.DependencyInjection;

var sp = new ServiceCollection().AddLogging().AddAuthorization()
    .AddSingleton<IAuthorizationHandler>(new ByRole("Owner"))
    .AddSingleton<IAuthorizationHandler>(new ByRole("Manager"))
    .AddSingleton<IAuthorizationHandler, Block>()
    .BuildServiceProvider();
var authz = sp.GetRequiredService<IAuthorizationService>();
var policy = new AuthorizationPolicyBuilder().AddRequirements(new Req()).Build();

ClaimsPrincipal U(params Claim[] cs) => new(new ClaimsIdentity(cs, "t"));
var users = new[]
{
    U(new Claim(ClaimTypes.Role, "Owner")),
    U(new Claim(ClaimTypes.Role, "Manager")),
    U(),
    U(new Claim(ClaimTypes.Role, "Owner"), new Claim("status", "banned")),
};
foreach (var u in users)
    Console.WriteLine((await authz.AuthorizeAsync(u, policy)).Succeeded);

class Req : IAuthorizationRequirement;

class ByRole(string role) : AuthorizationHandler<Req> {
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext c, Req r) {
        if (c.User.IsInRole(role)) c.Succeed(r);
        return Task.CompletedTask;
    }
}

class Block : IAuthorizationHandler {
    public Task HandleAsync(AuthorizationHandlerContext c) {
        if (c.User.HasClaim("status", "banned")) c.Fail();
        return Task.CompletedTask;
    }
}
