using System.Security.Claims;
using System.Text.Encodings.Web;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.Options;

var builder = WebApplication.CreateBuilder();
builder.Logging.ClearProviders();
builder.WebHost.UseUrls("http://127.0.0.1:0");
builder.Services.AddAuthentication("hdr")
    .AddScheme<AuthenticationSchemeOptions, HdrAuth>("hdr", _ => { });
builder.Services.AddAuthorization(o =>
{
    // Endpoint KHÔNG có attribute phân quyền nào
    o.FallbackPolicy = new AuthorizationPolicyBuilder()
        .RequireAuthenticatedUser().Build();
    // Endpoint có [Authorize] / RequireAuthorization() trần
    o.DefaultPolicy = new AuthorizationPolicyBuilder()
        .RequireAuthenticatedUser()
        .RequireClaim("vip").Build();
});
var app = builder.Build();
app.UseAuthentication();
app.UseAuthorization();
app.MapGet("/a", () => "a");
app.MapGet("/b", () => "b").AllowAnonymous();
app.MapGet("/c", () => "c").RequireAuthorization();

await app.StartAsync();
using var http = new HttpClient { BaseAddress = new Uri(app.Urls.First()) };
foreach (var p in new[] { "/a", "/b", "/c" })
    Console.WriteLine((int)(await http.GetAsync(p)).StatusCode);
await app.StopAsync();

class HdrAuth(IOptionsMonitor<AuthenticationSchemeOptions> o, ILoggerFactory l, UrlEncoder e)
    : AuthenticationHandler<AuthenticationSchemeOptions>(o, l, e)
{
    protected override Task<AuthenticateResult> HandleAuthenticateAsync() =>
        Task.FromResult(AuthenticateResult.Success(new AuthenticationTicket(
            new ClaimsPrincipal(new ClaimsIdentity([new Claim(ClaimTypes.Name, "an")], "hdr")), "hdr")));
}

