var edit = new OperationAuthorizationRequirement { Name = "Edit" };

ClaimsPrincipal U(string id) => new(new ClaimsIdentity(
    [new Claim(ClaimTypes.NameIdentifier, id)], "t"));
var doc = new Doc("u1");

Console.WriteLine((await authz.AuthorizeAsync(U("u1"), doc, edit)).Succeeded);
Console.WriteLine((await authz.AuthorizeAsync(U("u2"), doc, edit)).Succeeded);
Console.WriteLine((await authz.AuthorizeAsync(U("u1"), null, edit)).Succeeded);

record Doc(string OwnerId);

class OwnerHandler : AuthorizationHandler<OperationAuthorizationRequirement, Doc>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext c, OperationAuthorizationRequirement r, Doc d)
    {
        if (c.User.FindFirstValue(ClaimTypes.NameIdentifier) == d.OwnerId)
            c.Succeed(r);
        return Task.CompletedTask;
    }
}

